/// <summary>
/// contract class <c>AVACRLCreditOverrunContract</c>
/// </summary>
[DataContractAttribute]
final class AVACRLCreditOverrunContract
{
    AmountMST   overrunLimit;
    Days        daysAfterInvoice;
    str         packedQuery;

}

Method.Source:
/// <summary>
/// parmPackedQuery method
/// </summary>
/// <param name = "_packedQuery">str</param>
/// <returns>str</returns>
[
DataMemberAttribute,
AifQueryTypeAttribute('_packedQuery', queryStr(AVACRLReportResultQuery))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// parmOverrunLimit method
/// </summary>
/// <param name = "_limit">AmountMST</param>
/// <returns>AmountMST</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@NDX:NXACRLMinAmount")),
    SysOperationHelpTextAttribute(literalStr("@NDX:NXACRLMinAmountHT")),
    SysOperationDisplayOrderAttribute('1')
]
public AmountMST parmOverrunLimit(AmountMST _limit = overrunLimit)
{
    overrunLimit = _limit;

    return overrunLimit;
}

/// <summary>
/// parmDaysAfterInvoice method
/// </summary>
/// <param name = "_days">Days</param>
/// <returns>Days</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@NDX:NXACRLDaysAfterInvoice")),
    SysOperationDisplayOrderAttribute('2')
]
public Days parmDaysAfterInvoice(Days _days = daysAfterInvoice)
{
    daysAfterInvoice = _days;

    return daysAfterInvoice;
}
